from collections import deque
G=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
def comps(g):
 h,w=len(g),len(g[0]); seen=set(); cs=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=0 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<h and 0<=b<w and g[a][b]==0 and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
   cs.append(cells)
 return sorted(cs,key=len,reverse=True)
for i,c in enumerate(comps(G)):
 print(i,len(c), min(x for x,y in c),max(x for x,y in c),min(y for x,y in c),max(y for x,y in c),sorted(c))
